import React, { useEffect, useState } from 'react'
import useApi from '../../hooks/useApi'
import entitiesApi from '../../api/entitiesApi'
import { Link, useNavigate } from 'react-router-dom'
import { getLoggedInUser } from '../../helpers/authUtils'

export default function Followers() {
  const [follower, setFollower] = useState()
  const navigate = useNavigate()
  const [followers, setFollowers] = useState([])

      const [user, setUser] = useState()


    useEffect(() => {
        setUser(getLoggedInUser())

    }, [])

  const entitiesActionsApi = useApi(entitiesApi.entitiesAction)
  const getEntityFollowers = async () => {
      setFollowers([])
      await entitiesActionsApi.request({
          "action": "GetEntityFollowers"
      })
  }

  useEffect(() => {
    if (entitiesActionsApi.data && entitiesActionsApi.data.length) {

        setFollowers(entitiesActionsApi.data)
    }
    console.log('entitiesActionsApi.data', entitiesActionsApi.data)
}, [entitiesActionsApi.data])
  useEffect(() => {

      getEntityFollowers()
  }, [])

  const createConversationName=(phone)=> {
    const phonesAlph = [user?.phone, phone].sort();
    const to= `${phonesAlph[0]}__${phonesAlph[1]}`;
    console.log("Go", to)
      navigate(`/chat/${to}`);
  }

  return (
    <div>
      {followers
        .filter((u) => u.phone !== user?.phone)
        .map((u) => (
          
            <div onClick={()=>createConversationName(u.phone)} key={u.first_name}>{u.first_name} {u.last_name}</div>
          
        ))}
    </div>
  );
}
